import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import ReactMarkdown from 'react-markdown';
import Toast from './Toast';
import LogsViewer from './LogsViewer';
import KnowledgeManager from './KnowledgeManager';
import './App.css';

const BACKEND_URL = process.env.REACT_APP_BACKEND_URL || 'http://localhost:8001';

const generateUUID = () => {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
};

function App() {
  // --- STATE ---
  const [config, setConfig] = useState({
    app_name: "AI Assistant", 
    app_subtitle: "Connecting...",
    welcome_message: "Please wait...",
    primary_color: "#333", secondary_color: "#555", logo_emoji: "⏳"
  });

  const [profiles, setProfiles] = useState([]); 
  const [activeProfile, setActiveProfile] = useState("default"); // Importante: Default inicial

  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [systemStatus, setSystemStatus] = useState(null);
  const [indexStatus, setIndexStatus] = useState(null);
  const [ingesting, setIngesting] = useState(false);
  const [ingestionMessage, setIngestionMessage] = useState('');
  const [showIngestionMenu, setShowIngestionMenu] = useState(false);
  const [showUrlInput, setShowUrlInput] = useState(false);
  const [urlInput, setUrlInput] = useState('');
  const [toast, setToast] = useState(null);
  const [isRateLimited, setIsRateLimited] = useState(false);
  const [retryTimer, setRetryTimer] = useState(0);
  const [showLogs, setShowLogs] = useState(false);
  const [showManager, setShowManager] = useState(false);

  // O sessionId começa null e será definido assim que soubermos qual perfil está ativo
  const [sessionId, setSessionId] = useState(null);

  const fileInputRef = useRef(null);
  const messagesEndRef = useRef(null);
  const retryTimerRef = useRef(null);

  // 1. Carga Inicial (Config + Perfis)
  useEffect(() => {
    fetchInitialConfig();
  }, []);

  // 2. Quando o Perfil Ativo mudar, carregamos a Sessão correspondente
  useEffect(() => {
    if (activeProfile) {
        loadSessionForProfile(activeProfile);
    }
  }, [activeProfile]);

  // 3. Quando a Sessão mudar, carregamos o histórico e status
  useEffect(() => {
    if (sessionId) {
        console.log(`🔄 Session Changed: ${sessionId} (Profile: ${activeProfile})`);
        fetchHistory(sessionId);
        checkSystemHealth();
        checkIndexStatus();
    }
  }, [sessionId]);

  const fetchInitialConfig = async () => {
    try {
        const configRes = await axios.get(`${BACKEND_URL}/api/config`);
        setConfig(configRes.data);
        applyTheme(configRes.data);
        document.title = configRes.data.app_name;

        // Pega qual perfil está ativo no backend
        const profilesRes = await axios.get(`${BACKEND_URL}/api/config/profiles`);
        setProfiles(profilesRes.data.profiles || []);

        // Isso vai disparar o useEffect [activeProfile]
        setActiveProfile(profilesRes.data.active || "default");

    } catch (error) {
        console.error("Erro inicial:", error);
        setConfig({app_name: "Offline", app_subtitle: "Connection Error", welcome_message: "Error", primary_color: "#666", secondary_color: "#888", logo_emoji: "🔌"});
        // Fallback de sessão para não quebrar a UI
        loadSessionForProfile("offline");
    }
  };

  // --- LÓGICA DE SESSÃO POR PERFIL ---
  const loadSessionForProfile = (profileName) => {
      const storageKey = `chat_session_${profileName}`; // Chave única por perfil
      let savedId = localStorage.getItem(storageKey);

      if (!savedId) {
          savedId = generateUUID();
          localStorage.setItem(storageKey, savedId);
      }

      setSessionId(savedId);
  };

  // --- TROCA DE PERFIL ---
  const handleProfileSwitch = async (e) => {
      const newProfile = e.target.value;
      if (!newProfile) return;

      try {
          // 1. Avisa o backend para trocar a configuração (Prompt, Coleção, Cores)
          await axios.post(`${BACKEND_URL}/api/config/switch`, { profile_id: newProfile });

          showToast(`Switched to ${newProfile}`, "success");

          // 2. Atualiza o state local (isso vai disparar o useEffect que troca a sessão)
          // Limpamos as mensagens para não "piscar" conteúdo antigo
          setMessages([]); 
          setActiveProfile(newProfile);

          // 3. Recarrega as cores e textos do novo perfil
          const configRes = await axios.get(`${BACKEND_URL}/api/config`);
          setConfig(configRes.data);
          applyTheme(configRes.data);

      } catch (err) {
          showToast("Failed to switch profile", "error");
      }
  };

  const fetchHistory = async (sid) => { 
      try { 
          const res = await axios.get(`${BACKEND_URL}/api/chat/history/${sid}`); 
          if (res.data.history) setMessages(res.data.history); 
          else setMessages([]); // Se não tiver histórico, limpa a tela
      } catch { setMessages([]); } 
  };

  const applyTheme = (t) => { if(t.primary_color) document.documentElement.style.setProperty('--primary-color', t.primary_color); if(t.secondary_color) document.documentElement.style.setProperty('--secondary-color', t.secondary_color); };
  const scrollToBottom = () => messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  useEffect(() => scrollToBottom(), [messages]);

  const showToast = (message, type = 'info', duration=5000) => setToast({ message, type, duration });
  const closeToast = () => setToast(null);
  const checkSystemHealth = async () => { try { const r = await axios.get(`${BACKEND_URL}/api/health`); setSystemStatus(r.data); } catch { setSystemStatus({ status: 'error' }); } };
  const checkIndexStatus = async () => { try { const r = await axios.get(`${BACKEND_URL}/api/index-status`); setIndexStatus(r.data); } catch {} };
  const handleCopySessionId = () => { navigator.clipboard.writeText(sessionId); showToast("Session ID copied!", "success", 2000); };

  // Reset agora reseta APENAS a sessão do perfil atual
  const handleNewSession = () => {
    const newId = generateUUID();
    setSessionId(newId);
    // Salva na chave específica do perfil ativo
    localStorage.setItem(`chat_session_${activeProfile}`, newId);
    setMessages([]); 
    showToast(`New conversation started for ${activeProfile}`, "info");         
  };

  const handleCopyMessage = (text) => { navigator.clipboard.writeText(text); showToast("Markdown copied!", "success", 2000); };

  const handleFeedback = async (index, score) => {
    const message = messages[index]; const prev = messages[index-1]; if(!message||!prev) return;
    const upd = [...messages]; upd[index] = {...message, feedback: score}; setMessages(upd);
    try { await axios.post(`${BACKEND_URL}/api/feedback/`, { user_question: prev.content, bot_response: message.content, score }); if(score>0) showToast("Thanks!", "success"); else showToast("Noted.", "info"); } catch {}
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!input.trim() || loading || isRateLimited) return;

    const userMessage = { role: 'user', content: input, timestamp: new Date().toISOString() };
    setMessages(p => [...p, userMessage]); const txt = input; setInput(''); setLoading(true);
    try {
        setMessages(p => [...p, { role: 'assistant', content: '', timestamp: new Date().toISOString(), id: Date.now() }]);
        const res = await fetch(`${BACKEND_URL}/api/chat/stream`, { method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({ message: txt, session_id: sessionId }) });
        const reader = res.body.getReader(); const decoder = new TextDecoder();
        let buf = "", sources = [];
        while(true) {
            const {done, value} = await reader.read(); if(done) break;
            const lines = decoder.decode(value, {stream:true}).split('\n');
            for(const l of lines) {
                if(!l.trim()) continue;
                try {
                    const d = JSON.parse(l);
                    if(d.type==='token') { buf+=d.content; setMessages(p=>{ const n=[...p]; n[n.length-1].content=buf; return n; }); }
                    else if(d.type==='sources') sources=d.content;
                } catch {}
            }
        }
        if(sources.length) setMessages(p=>{ const n=[...p]; n[n.length-1].content = buf + "\n\n---\n📚 **Sources:**\n"+sources.map(s=>`- \`${s}\``).join('\n'); return n; });
    } catch { setMessages(p=>{ const n=[...p]; n[n.length-1].content="Error"; n[n.length-1].error=true; return n; }); }
    finally { setLoading(false); }
  };

  const handleFileUpload = async (e) => {
      const files = e.target.files; if(!files.length) return; setIngesting(true); setShowIngestionMenu(false);
      try { const fd = new FormData(); for(let i=0; i<files.length; i++) fd.append('files', files[i]); await axios.post(`${BACKEND_URL}/api/ingest-pdf`, fd); showToast("Success", "success"); checkIndexStatus(); } catch { showToast("Error", "error"); } finally { setIngesting(false); }
  };

  const handleUrlIngestion = async () => {
      if(!urlInput) return; setIngesting(true); setShowUrlInput(false);
      try { const fd = new FormData(); fd.append('url', urlInput); await axios.post(`${BACKEND_URL}/api/ingest-url`, fd); showToast("Success", "success"); checkIndexStatus(); } catch { showToast("Error", "error"); } finally { setIngesting(false); setUrlInput(''); }
  };

  return (
    <div className="app">
      <div className="sidebar">
        <div className="sidebar-header"><h2>{config.logo_emoji} {config.app_name}</h2><p className="subtitle">{config.app_subtitle}</p></div>
        <div className="sidebar-content">

          {/* SELETOR DE PERFIL */}
          {profiles.length > 0 && (
            <div className="profile-selector">
                <label>Active Profile:</label>
                <select value={activeProfile} onChange={handleProfileSwitch} className="profile-dropdown">
                    {profiles.map(p => (
                        <option key={p} value={p}>{p.toUpperCase()}</option>
                    ))}
                </select>
            </div>
          )}

          <div className="status-section">
            <h3>📊 Status</h3>
            {systemStatus && ( <div className="status-info"> <div className={`status-badge status-${systemStatus.status}`}>{systemStatus.status==='healthy'?'✅ Online':'⚠️ Degraded'}</div> <div className="status-details"> <div className="status-item"><span>API Key:</span><span>{systemStatus.api_key_configured?'✅':'❌'}</span></div> <div className="status-item"><span>DB:</span><span>{systemStatus.database_loaded?'✅':'❌'}</span></div> <div className="status-item" onClick={handleCopySessionId} style={{cursor:'pointer'}} title="Copy Session"><span>Session:</span><span style={{fontSize:'11px', fontFamily:'monospace'}}>{sessionId ? sessionId.slice(0,6) : '...'}...</span></div> </div> </div> )}
          </div>

          <div className="index-section"><h3>📊 Knowledge Base</h3>{indexStatus && <p className="index-count">{indexStatus.document_count} chunks</p>}<button onClick={() => setShowManager(true)} className="manage-link">Manage Files ⚙️</button></div>

          <div className="actions-section">
            <button onClick={() => setShowIngestionMenu(!showIngestionMenu)} className="action-button ingestion-button" disabled={ingesting}>📚 Add Knowledge</button>
            {showIngestionMenu && !ingesting && (<div className="ingestion-menu"><button onClick={() => fileInputRef.current?.click()} className="ingestion-option">📄 PDF</button><input ref={fileInputRef} type="file" accept=".pdf" multiple style={{display:'none'}} onChange={handleFileUpload} /><button onClick={() => {setShowUrlInput(true); setShowIngestionMenu(false);}} className="ingestion-option">🌐 URL</button></div>)}
            {showUrlInput && !ingesting && (<div className="url-input-container"><input type="text" value={urlInput} onChange={(e)=>setUrlInput(e.target.value)} placeholder="https://..." className="url-input" /><div className="url-buttons"><button onClick={handleUrlIngestion} className="url-button url-button-submit">Add</button><button onClick={()=>setShowUrlInput(false)} className="url-button url-button-cancel">Cancel</button></div></div>)}
            {ingestionMessage && <div className="ingestion-status ingesting">{ingestionMessage}</div>}
          </div>

          <div className="actions-section"><button onClick={()=>setShowLogs(true)} className="action-button logs-button">📊 System Logs</button></div>
          <button onClick={handleNewSession} className="clear-button">✨ New Chat</button>
        </div>
      </div>

      <div className="main-content">
        <div className="chat-header"><h1>{config.logo_emoji} {config.app_name}</h1><p className="header-subtitle">{config.app_subtitle}</p></div>
        <div className="messages-container">
          {messages.length === 0 ? (
            <div className="welcome-message"><div className="welcome-icon">{config.logo_emoji}</div><h2>Hello!</h2><p>{config.welcome_message}</p></div>
          ) : (
            messages.map((msg, index) => (
              <div key={index} className={`message-group ${msg.role}`}>
                <div className={`message message-${msg.role} ${msg.error ? 'message-error' : ''}`}>
                  <div className="message-icon">{msg.role === 'user' ? '👤' : msg.error ? '❌' : config.logo_emoji}</div>
                  <div className="message-content">
                    <div className="message-text"><ReactMarkdown components={{a: ({node, ...props}) => <a {...props} target="_blank" />}}>{msg.content}</ReactMarkdown></div>
                    {msg.role === 'assistant' && !msg.error && (
                      <div className="message-footer">
                        <span className="message-time">{new Date(msg.timestamp).toLocaleTimeString()}</span>
                        <div className="feedback-actions">
                          <button className="feedback-btn" onClick={() => handleCopyMessage(msg.content)} title="Copy">📋</button>
                          <button className={`feedback-btn ${msg.feedback === 1 ? 'active-like' : ''}`} onClick={()=>handleFeedback(index, 1)} disabled={msg.feedback !== undefined}>👍</button>
                          <button className={`feedback-btn ${msg.feedback === -1 ? 'active-dislike' : ''}`} onClick={()=>handleFeedback(index, -1)} disabled={msg.feedback !== undefined}>👎</button>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))
          )}
          {loading && (<div className="message message-assistant"><div className="message-icon">{config.logo_emoji}</div><div className="message-content"><div className="loading-indicator"><div className="loading-dot"></div><div className="loading-dot"></div><div className="loading-dot"></div></div></div></div>)}
          <div ref={messagesEndRef} />
        </div>
        <div className="input-container">
          <form onSubmit={handleSubmit} className="input-form">
            <input type="text" value={input} onChange={(e)=>setInput(e.target.value)} className="chat-input" disabled={loading} placeholder="Ask..." />
            <button type="submit" className="send-button" disabled={loading || !input.trim()}>{loading?'⏳':'🚀'}</button>
          </form>
        </div>
      </div>

      {toast && <Toast message={toast.message} type={toast.type} duration={toast.duration} onClose={closeToast} />}
      {showLogs && <LogsViewer onClose={()=>setShowLogs(false)} />}
      {showManager && <KnowledgeManager onClose={() => { setShowManager(false); checkIndexStatus(); }} backendUrl={BACKEND_URL} />}
    </div>
  );
}

export default App;
